// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!DOCTYPE html>\n<html lang=\"az\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Qala Keşikçisi</title>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Unbounded:wght@500;800&family=Manrope:wght@400;600;800&display=swap\">\n<style>\n:root{--bg:#dfe9ea;--ink:#eef6f6;--mut:#9db8bb;--gold:#f5c451;--cy:#4cc9f0;--co:#ff6b6b;--glass:rgba(10,26,32,.82);--w:360px;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#081318}}\n:root[data-theme=\"dark\"]{--bg:#081318}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{height:100%;margin:0}\nbody{background:radial-gradient(120% 70% at 50% 0%,#17343c 0%,var(--bg) 70%);color:var(--ink);font-family:Manrope,\"Segoe UI\",system-ui,sans-serif;overflow:hidden;touch-action:none;user-select:none;-webkit-user-select:none;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px}\n[hidden]{display:none!important}\n#top,#bar{width:var(--w)}\n#top{display:flex;justify-content:space-between;font-family:Unbounded,\"Trebuchet MS\",sans-serif;font-weight:800;font-size:1.05rem}\n#top span:nth-child(2){color:var(--gold)}#top span:nth-child(1){color:var(--co)}\ncanvas{width:var(--w);display:block;border-radius:18px;box-shadow:0 18px 44px rgba(0,0,0,.4)}\n#bar{display:flex;flex-direction:column;gap:8px}\n.r{display:flex;gap:8px}\n.tb,.bt{flex:1;display:flex;flex-direction:column;align-items:center;gap:1px;padding:7px 4px;border-radius:14px;border:1.5px solid rgba(255,255,255,.14);background:var(--glass);color:var(--ink);font:inherit;font-size:.75rem;cursor:pointer}\n.tb b{font-size:1.15rem;line-height:1.2}.tb em{font-style:normal;color:var(--gold);font-weight:800}\n.tb.on{border-color:var(--gold);box-shadow:0 0 0 2px rgba(245,196,81,.3)}\n.tb.no{opacity:.45}\n.bt{flex-direction:row;justify-content:center;padding:11px 8px;font-weight:800;font-size:.85rem}\n#nw{flex:3;background:linear-gradient(135deg,#ffd978,#ffb02e);color:#1a1204;border:0}\n#nw:disabled{opacity:.5}\nbutton:focus-visible{outline:3px solid var(--cy);outline-offset:2px}\n#toast{position:fixed;left:50%;top:26%;transform:translate(-50%,0);font-family:Unbounded,sans-serif;font-weight:800;font-size:1.05rem;color:var(--gold);pointer-events:none;opacity:0;text-shadow:0 4px 20px rgba(0,0,0,.6);white-space:nowrap}\n#toast.on{animation:tt 1.2s ease-out}\n@keyframes tt{0%{opacity:0;transform:translate(-50%,10px)}20%{opacity:1}100%{opacity:0;transform:translate(-50%,-26px)}}\n@media (prefers-reduced-motion:reduce){#toast.on{animation:none;opacity:1}}\n#ov{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(4,14,18,.55)}\n.card{width:min(100%,390px);padding:28px 24px;border-radius:24px;background:var(--glass);border:1px solid rgba(255,255,255,.14);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);text-align:center;display:flex;flex-direction:column;gap:14px}\nh1{margin:0;font-family:Unbounded,\"Trebuchet MS\",sans-serif;font-weight:800;font-size:clamp(1.5rem,7.5vw,2.1rem);line-height:1.15;background:linear-gradient(120deg,#f5c451,#4cc9f0 80%);-webkit-background-clip:text;background-clip:text;color:transparent}\n.card p{margin:0;color:var(--mut);line-height:1.5;font-size:.92rem}\n#go{font:inherit;font-weight:800;border:0;border-radius:16px;padding:15px;cursor:pointer;color:#1a1204;background:linear-gradient(135deg,#ffd978,#ffb02e);box-shadow:0 8px 28px rgba(255,176,46,.32)}\n</style>\n</head>\n<body>\n<div id=\"top\"><span id=\"lf\">♥ 20</span><span id=\"gd\">🪙 0</span><span id=\"wv\">Dalğa 1</span></div>\n<canvas id=\"c\"></canvas>\n<div id=\"bar\">\n  <div class=\"r\" id=\"tw\"></div>\n  <div class=\"r\" id=\"up\" hidden>\n    <button class=\"tb\" id=\"ug\"></button><button class=\"tb\" id=\"sl\"></button>\n  </div>\n  <div class=\"r\"><button class=\"bt\" id=\"nw\">▶ Dalğanı başlat</button><button class=\"bt\" id=\"sp\">×1</button><button class=\"bt\" id=\"mu\" aria-label=\"Səs\">🔊</button></div>\n</div>\n<div id=\"toast\"></div>\n<div id=\"ov\">\n  <div class=\"card\">\n    <h1 id=\"ot\">Qala Keşikçisi</h1>\n    <p id=\"om\">Qaranlıq məxluqlar qalaya doğru gəlir. Yolun kənarında qüllələr tik, yüksəlt və hər dalğanı dayandır. Oxatan sürətlidir, top partlayış sahəsi vurur, buz isə düşmənləri yavaşladır.</p>\n    <button id=\"go\">Başla</button>\n  </div>\n</div>\n<script>\nconst COLS=8,ROWS=10,$=i=>document.getElementById(i),cv=$('c'),g=cv.getContext('2d'),R=Math.random,TAU=Math.PI*2;\nconst WP=[[-1,1],[6,1],[6,3],[1,3],[1,5],[6,5],[6,7],[1,7],[1,9],[8,9]];\nconst TW=[{n:'Oxatan',ic:'🏹',c:50,r:2.3,rt:.55,d:9,col:'#4cc9f0'},{n:'Top',ic:'💣',c:100,r:2.5,rt:1.5,d:34,sp:.95,col:'#ff9a5c'},{n:'Buz',ic:'❄️',c:75,r:2,rt:.8,d:3,col:'#b8e8ff'}];\nconst ET=[{hp:40,v:1.2,r:.3,g:8,c:'#ffb347'},{hp:22,v:1.9,r:.26,g:6,c:'#ff5d73'},{hp:150,v:.8,r:.38,g:20,c:'#b388ff'},{hp:1400,v:.55,r:.55,g:200,c:'#ff3d81'}];\nlet cell=40,bgc,pts=[],Lc=[],tot=0,blk=new Set(),Tw=[],en=[],pj=[],pa=[],pop=[],st='menu',lives=20,gold=170,wave=0,waveOn=false,Q=[],sT=0,spd=1,selT=null,sel=null,hov=null,best=0,t=0,last=0,sh=0,ac,muted=false,kills=0;\ntry{best=+localStorage.getItem('qk-best')||0;muted=localStorage.getItem('qk-mute')==='1'}catch(e){}\n$('mu').textContent=muted?'🔇':'🔊';\nconst toast=s=>{const e=$('toast');e.textContent=s;e.classList.remove('on');void e.offsetWidth;e.classList.add('on')};\nfunction snd(f,d,ty,v,f2){if(muted||!ac)return;try{const n=ac.currentTime,o=ac.createOscillator(),a=ac.createGain();o.type=ty;o.frequency.setValueAtTime(f,n);o.frequency.exponentialRampToValueAtTime(f2,n+d);a.gain.setValueAtTime(v,n);a.gain.exponentialRampToValueAtTime(.001,n+d);o.connect(a);a.connect(ac.destination);o.start();o.stop(n+d)}catch(e){}}\nconst rr=(x,y,w,h,r)=>{g.beginPath();g.roundRect(x,y,w,h,r)};\nfunction glow(x,y,r,c,a){const q=g.createRadialGradient(x,y,0,x,y,r);q.addColorStop(0,c);q.addColorStop(1,'rgba(0,0,0,0)');g.globalAlpha=a;g.fillStyle=q;g.fillRect(x-r,y-r,r*2,r*2);g.globalAlpha=1}\n\nfunction size(){\n  const D=Math.min(devicePixelRatio||1,2);cell=Math.floor(Math.max(28,Math.min(innerWidth/COLS,(innerHeight-215)/ROWS,64)));\n  const w=cell*COLS,h=cell*ROWS;document.documentElement.style.setProperty('--w',w+'px');cv.width=w*D;cv.height=h*D;cv.style.height=h+'px';g.setTransform(D,0,0,D,0,0);\n  pts=WP.map(p=>[(p[0]+.5)*cell,(p[1]+.5)*cell]);Lc=[0];for(let i=1;i<pts.length;i++)Lc.push(Lc[i-1]+Math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]));tot=Lc[Lc.length-1];\n  blk=new Set();for(let i=1;i<WP.length;i++){const[a,b]=[WP[i-1],WP[i]];for(let c=Math.min(a[0],b[0]);c<=Math.max(a[0],b[0]);c++)for(let r=Math.min(a[1],b[1]);r<=Math.max(a[1],b[1]);r++)blk.add(c+','+r)}\n  bgc=document.createElement('canvas');bgc.width=w*D;bgc.height=h*D;const b=bgc.getContext('2d');b.setTransform(D,0,0,D,0,0);\n  const q=b.createLinearGradient(0,0,0,h);q.addColorStop(0,'#12272f');q.addColorStop(1,'#0b1a20');b.fillStyle=q;b.fillRect(0,0,w,h);\n  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++)if(!blk.has(c+','+r)){b.fillStyle=(r+c)%2?'#163039':'#142b34';b.beginPath();b.roundRect(c*cell+2,r*cell+2,cell-4,cell-4,6);b.fill()}\n  b.lineJoin='round';b.lineCap='round';b.beginPath();pts.forEach((p,i)=>i?b.lineTo(p[0],p[1]):b.moveTo(p[0],p[1]));\n  b.strokeStyle='#232a3f';b.lineWidth=cell*.92;b.stroke();b.strokeStyle='#2c3450';b.lineWidth=cell*.7;b.stroke();b.setLineDash([cell*.12,cell*.28]);b.strokeStyle='rgba(245,196,81,.28)';b.lineWidth=2;b.stroke();b.setLineDash([]);\n  const gx=w-cell*.2,gy=pts[pts.length-2][1];const gl=b.createRadialGradient(gx,gy,0,gx,gy,cell*1.2);gl.addColorStop(0,'rgba(76,201,240,.7)');gl.addColorStop(1,'rgba(76,201,240,0)');b.fillStyle=gl;b.fillRect(gx-cell*1.3,gy-cell*1.3,cell*2.6,cell*2.6);\n  const sx=cell*.1,sy=pts[1][1],sl=b.createRadialGradient(sx,sy,0,sx,sy,cell*1.1);sl.addColorStop(0,'rgba(255,93,115,.6)');sl.addColorStop(1,'rgba(255,93,115,0)');b.fillStyle=sl;b.fillRect(0,sy-cell*1.2,cell*2,cell*2.4);\n}\nfunction pos(d){let i=1;while(i<Lc.length-1&&Lc[i]<d)i++;const f=(d-Lc[i-1])/(Lc[i]-Lc[i-1]);return[pts[i-1][0]+(pts[i][0]-pts[i-1][0])*f,pts[i-1][1]+(pts[i][1]-pts[i-1][1])*f]}\nfunction buildBar(){$('tw').innerHTML=TW.map((x,i)=>'<button class=\"tb\" data-i=\"'+i+'\"><b>'+x.ic+'</b>'+x.n+'<em>🪙'+x.c+'</em></button>').join('');document.querySelectorAll('#tw .tb').forEach(b=>b.onclick=()=>{selT=selT==+b.dataset.i?null:+b.dataset.i;sel=null})}\nfunction start(){\n  try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();ac.resume()}catch(e){}\n  Tw=[];en=[];pj=[];pa=[];pop=[];lives=20;gold=170;wave=0;waveOn=false;Q=[];selT=null;sel=null;kills=0;sh=0;st='play';$('ov').hidden=true;\n}\nfunction mkWave(n){const q=[];if(n%10==0)q.push(3);const c=6+n*2;for(let i=0;i<c;i++){const r=R();q.push(n>=3&&r<.18+Math.min(.2,n*.01)?2:n>=2&&r<.5?1:0)}return q.sort(()=>R()-.5)}\nfunction nextWave(){if(waveOn||st!='play')return;wave++;Q=mkWave(wave);waveOn=true;sT=0;toast('Dalğa '+wave+(wave%10==0?' · Boss':''));snd(220,.4,'sawtooth',.05,330)}\nfunction spawn(k){const e=ET[k],s=k==3?1+wave*.12:1+(wave-1)*.24;en.push({k,d:0,hp:e.hp*s,m:e.hp*s,slow:0})}\nfunction boom(x,y,c,n){for(let i=0;i<n;i++){const a=R()*TAU,s=40+R()*150,l=.35+R()*.4;pa.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,l,m:l,c,r:1.5+R()*2.5})}}\nfunction dmg(e,d){e.hp-=d;if(e.hp<=0&&!e.dead){e.dead=1;const[x,y]=pos(e.d),gd=ET[e.k].g+(wave>10?Math.floor(wave/5):0);gold+=gd;kills++;boom(x,y,ET[e.k].c,e.k==3?50:12);pop.push({x,y,s:'+'+gd,l:1});snd(e.k==3?100:260,e.k==3?.6:.12,'triangle',.05,60);if(e.k==3)sh=16}}\nfunction tcost(T){return Math.round(TW[T.k].c*(T.lv==1?.9:1.7))}\nfunction sold(T){return Math.floor(T.inv*.7)}\nfunction update(dt){\n  t+=dt;\n  if(waveOn){sT-=dt;if(Q.length&&sT<=0){spawn(Q.shift());sT=Math.max(.35,.95-wave*.03)}\n    if(!Q.length&&!en.length){waveOn=false;const b=20+wave*3;gold+=b;toast('Dalğa tamam  +'+b+' 🪙');if(wave>best){best=wave;try{localStorage.setItem('qk-best',best)}catch(e){}}}}\n  en.forEach(e=>{e.slow=Math.max(0,e.slow-dt);e.d+=ET[e.k].v*cell*(e.slow>0?.45:1)*dt;if(e.d>=tot&&!e.dead){e.dead=1;e.leak=1;lives-=e.k==3?5:1;sh=12;snd(150,.3,'square',.06,60)}});\n  en=en.filter(e=>!e.dead);\n  Tw.forEach(T=>{\n    T.cd-=dt;let tg=null,bd=-1;const rng=T.r*cell,[tx,ty]=[(T.c+.5)*cell,(T.r0+.5)*cell];\n    en.forEach(e=>{const[x,y]=pos(e.d);if(Math.hypot(x-tx,y-ty)<=rng&&e.d>bd){bd=e.d;tg=e}});\n    if(tg){const[x,y]=pos(tg.d);T.a=Math.atan2(y-ty,x-tx);if(T.cd<=0){T.cd=T.rt;pj.push({x:tx,y:ty,e:tg,T});snd(T.k==1?160:T.k==2?900:700,.07,'square',.015,T.k==1?60:400)}}\n  });\n  pj.forEach(p=>{\n    if(p.e.dead){p.x=-99;return}\n    const[x,y]=pos(p.e.d),dx=x-p.x,dy=y-p.y,d=Math.hypot(dx,dy),s=(p.T.k==1?7:11)*cell*dt;\n    if(d<=s+4){p.x=-99;const T=p.T;\n      if(T.k==1){boom(x,y,'#ffb347',14);en.slice().forEach(e=>{const[ex,ey]=pos(e.d);if(Math.hypot(ex-x,ey-y)<TW[1].sp*cell)dmg(e,T.d)});sh=Math.max(sh,3)}\n      else{dmg(p.e,T.d);if(T.k==2)p.e.slow=1.6;boom(x,y,TW[T.k].col,4)}\n    }else{p.x+=dx/d*s;p.y+=dy/d*s}\n  });\n  pj=pj.filter(p=>p.x>-50);en=en.filter(e=>!e.dead);\n  if(lives<=0){lives=0;over()}\n}\nfunction over(){\n  st='end';if(wave>best){best=wave;try{localStorage.setItem('qk-best',best)}catch(e){}}\n  $('ot').textContent='Qala yıxıldı';$('om').textContent=wave+'-ci dalğaya çatdın, '+kills+' düşmən məhv etdin. Ən yaxşı nəticən: '+best+' dalğa.';$('go').textContent='Yenidən müdafiə et';\n  setTimeout(()=>{$('ov').hidden=false},800);\n}\nfunction drawTower(T,gh){\n  const x=(T.c+.5)*cell,y=(T.r0+.5)*cell,col=TW[T.k].col,a=gh?0:T.a;\n  g.globalAlpha=gh?.55:1;\n  g.beginPath();g.arc(x,y,cell*.38,0,TAU);g.fillStyle='#16242c';g.fill();g.strokeStyle=col;g.lineWidth=2.5;g.stroke();\n  g.save();g.translate(x,y);g.rotate(a);g.fillStyle=col;\n  if(T.k==0){g.fillRect(0,-cell*.05,cell*.36,cell*.1);g.beginPath();g.arc(0,0,cell*.14,0,TAU);g.fill()}\n  else if(T.k==1){g.fillRect(0,-cell*.1,cell*.34,cell*.2);g.beginPath();g.arc(0,0,cell*.19,0,TAU);g.fill()}\n  else{g.rotate(t*1.5-a);g.beginPath();for(let i=0;i<4;i++)g.lineTo(Math.cos(i*TAU/4)*cell*.22,Math.sin(i*TAU/4)*cell*.22);g.closePath();g.fill()}\n  g.restore();\n  if(!gh)for(let i=0;i<T.lv;i++){g.fillStyle='#f5c451';g.beginPath();g.arc(x-(T.lv-1)*cell*.06+i*cell*.12,y+cell*.3,cell*.04,0,TAU);g.fill()}\n  g.globalAlpha=1;\n}\nfunction ring(x,y,r,c){g.beginPath();g.arc(x,y,r,0,TAU);g.fillStyle=c+'22';g.fill();g.setLineDash([6,6]);g.strokeStyle=c+'aa';g.lineWidth=1.5;g.stroke();g.setLineDash([])}\nfunction render(dt){\n  const w=cell*COLS,h=cell*ROWS;g.save();g.drawImage(bgc,0,0,w,h);if(sh>.5)g.translate((R()-.5)*sh,(R()-.5)*sh);\n  if(st!='menu'){\n    if(sel)ring((sel.c+.5)*cell,(sel.r0+.5)*cell,sel.r*cell,TW[sel.k].col);\n    if(selT!==null&&hov&&!blk.has(hov[0]+','+hov[1])&&!Tw.some(T=>T.c==hov[0]&&T.r0==hov[1])){ring((hov[0]+.5)*cell,(hov[1]+.5)*cell,TW[selT].r*cell,TW[selT].col);drawTower({k:selT,c:hov[0],r0:hov[1],a:0,lv:1},true)}\n    Tw.forEach(T=>drawTower(T));\n    en.forEach(e=>{\n      const D=ET[e.k],[x,y]=pos(e.d),r=D.r*cell,bob=Math.sin(t*8+e.d)*1.5;\n      g.globalCompositeOperation='lighter';glow(x,y+bob,r*2.2,D.c,.4);g.globalCompositeOperation='source-over';\n      g.beginPath();const n=[0,3,6,8][e.k]||0;\n      if(e.k==0){g.arc(x,y+bob,r,0,TAU)}else{const nn=e.k==1?3:n;for(let i=0;i<nn;i++){const an=i*TAU/nn+(e.k==3?t:0)+Math.PI/2;g.lineTo(x+Math.cos(an)*r*(e.k==1?1.15:1),y+bob+Math.sin(an)*r*(e.k==1?1.15:1))}}\n      g.closePath();g.fillStyle=e.slow>0?'#7fd8ff':D.c;g.fill();g.strokeStyle='rgba(255,255,255,.6)';g.lineWidth=1.5;g.stroke();\n      g.fillStyle='#10161c';g.beginPath();g.arc(x-r*.3,y+bob-r*.1,r*.14,0,TAU);g.arc(x+r*.3,y+bob-r*.1,r*.14,0,TAU);g.fill();\n      if(e.hp<e.m){const bw=Math.max(cell*.5,r*1.8);g.fillStyle='rgba(0,0,0,.55)';g.fillRect(x-bw/2,y-r-9,bw,4);g.fillStyle=e.hp/e.m>.4?'#7ee6a8':'#ff5d73';g.fillRect(x-bw/2,y-r-9,bw*e.hp/e.m,4)}\n    });\n    g.globalCompositeOperation='lighter';\n    pj.forEach(p=>{const c=TW[p.T.k].col;glow(p.x,p.y,p.T.k==1?cell*.4:cell*.25,c,.9);g.fillStyle='#fff';g.beginPath();g.arc(p.x,p.y,p.T.k==1?5:3,0,TAU);g.fill()});\n    pa.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.l-=dt;g.globalAlpha=Math.max(0,p.l/p.m);g.fillStyle=p.c;g.beginPath();g.arc(p.x,p.y,p.r,0,TAU);g.fill()});\n    g.globalAlpha=1;g.globalCompositeOperation='source-over';pa=pa.filter(p=>p.l>0);\n    pop.forEach(p=>{p.l-=dt*1.2;p.y-=dt*28;g.globalAlpha=Math.max(0,Math.min(1,p.l*1.6));g.fillStyle='#f5c451';g.font='800 '+(cell*.3)+'px Unbounded,sans-serif';g.textAlign='center';g.fillText(p.s,p.x,p.y)});\n    g.globalAlpha=1;pop=pop.filter(p=>p.l>0);\n  }\n  g.restore();sh*=.9;\n  $('lf').textContent='♥ '+lives;$('gd').textContent='🪙 '+gold;$('wv').textContent='Dalğa '+(wave||1)+(wave?'':'');\n  document.querySelectorAll('#tw .tb').forEach((b,i)=>{b.classList.toggle('on',selT===i);b.classList.toggle('no',gold<TW[i].c)});\n  $('nw').disabled=waveOn||st!='play';$('nw').textContent=waveOn?'Dalğa gedir…':'▶ Dalğa '+(wave+1)+' başlat';\n  $('tw').hidden=!!sel;$('up').hidden=!sel;\n  if(sel){const mx=sel.lv>=3;$('ug').innerHTML='<b>⬆</b>'+(mx?'Maksimum':'Yüksəlt Sev.'+(sel.lv+1))+(mx?'':'<em>🪙'+tcost(sel)+'</em>');$('ug').classList.toggle('no',mx||gold<tcost(sel));$('sl').innerHTML='<b>💰</b>Sat<em>+'+sold(sel)+'</em>'}\n}\nfunction frame(ts){const dt=Math.min(.05,(ts-last)/1000||0);last=ts;if(st=='play')for(let i=0;i<spd;i++)update(dt);render(dt*(st=='play'?spd:1));requestAnimationFrame(frame)}\n\nconst cellAt=e=>{const b=cv.getBoundingClientRect(),c=Math.floor((e.clientX-b.left)/cell),r=Math.floor((e.clientY-b.top)/cell);return c>=0&&r>=0&&c<COLS&&r<ROWS?[c,r]:null};\ncv.addEventListener('pointermove',e=>{hov=cellAt(e)});\ncv.addEventListener('pointerdown',e=>{\n  hov=cellAt(e);if(!hov||st!='play')return;const[c,r]=hov,T=Tw.find(T=>T.c==c&&T.r0==r);\n  if(T){sel=sel===T?null:T;selT=null;return}\n  if(selT!==null&&!blk.has(c+','+r)){const d=TW[selT];if(gold>=d.c){gold-=d.c;Tw.push({k:selT,c,r0:r,r:d.r,rt:d.rt,d:d.d,cd:0,a:0,lv:1,inv:d.c});snd(500,.15,'triangle',.06,900);boom((c+.5)*cell,(r+.5)*cell,d.col,10)}else toast('Qızıl çatmır')}\n  else{sel=null;if(blk.has(c+','+r))selT=null}\n});\n$('ug').onclick=()=>{const T=sel;if(!T||T.lv>=3)return;const c=tcost(T);if(gold<c){toast('Qızıl çatmır');return}gold-=c;T.inv+=c;T.lv++;T.d*=1.6;T.r*=1.08;T.rt*=.9;snd(600,.2,'triangle',.06,1100);boom((T.c+.5)*cell,(T.r0+.5)*cell,'#f5c451',14)};\n$('sl').onclick=()=>{const T=sel;if(!T)return;gold+=sold(T);Tw=Tw.filter(x=>x!==T);sel=null;snd(300,.15,'sine',.05,200)};\n$('nw').onclick=nextWave;\n$('sp').onclick=()=>{spd=spd==1?2:1;$('sp').textContent='×'+spd};\n$('mu').onclick=()=>{muted=!muted;$('mu').textContent=muted?'🔇':'🔊';try{localStorage.setItem('qk-mute',muted?'1':'0')}catch(e){}};\n$('go').onclick=start;\naddEventListener('keydown',e=>{if(!$('ov').hidden&&(e.key=='Enter'||e.key==' ')){e.preventDefault();start()}else if(e.key==' '&&st=='play'){e.preventDefault();nextWave()}});\naddEventListener('resize',size);\nbuildBar();size();requestAnimationFrame(frame);\n</script>\n</body>\n</html>\n";
